functions.generateOfficePlaylist:
async function generateOfficePlaylist() {
  try {
    generateButton.disabled = true;
    newSearchesThisGeneration = 0;
    queriesAttemptedThisGeneration = new Set();
    playlistBox.style.display = "none";
    playlistResult.textContent = "";
    progressBox.textContent = "Przygotowuję profile...";

    const token = await getValidAccessToken();
    if (!token) throw new Error("Brak aktywnej sesji Spotify.");

    const total = Number(playlistLength.value);
    maxNewSearchesThisGeneration = searchBudgetForTarget(total);

    progressBox.textContent = "Sprzątam playlisty Office Music Mixer starsze niż 72 godziny...";
    const playlistCleanupResult = await cleanupOldOfficePlaylists(token);

    const selected = selectedProfiles();
    const bartek = selected.find(profile => profile.id === "bartek");
    if (!bartek) {
      throw new Error("Profil Bartka musi być aktywny. Jest głównym profilem tej aplikacji.");
    }
    if (!hasMusicProfile(bartek)) {
      throw new Error("Profil Bartka nie ma danych muzycznych. Wypełnij ankietę gustu lub dodaj gatunki/artystów wzorcowych.");
    }

    const mixProfiles = selected.filter(hasMusicProfile);
    const ignoredProfiles = selected.filter(profile => !hasMusicProfile(profile));

    progressBox.textContent = "Sprawdzam świeżość Last.fm (historia 10 min, baza tagów 60 min)...";
    await refreshLastFmBeforeGeneration(mixProfiles, total);

    progressBox.textContent = "Synchronizuję historię odtworzeń...";
    await syncSpotifyRecentHistory(token);
    const acquisitionBlocklists = generationBlocklists(selected);
    const acquisition = createCandidateAcquisition(mixProfiles, acquisitionBlocklists);

    progressBox.textContent =
      `Odświeżam artystów wzorcowych (budżet ${maxNewSearchesThisGeneration} nowych wyszukiwań)...`;
    await primeManualSeedArtists(token, mixProfiles, 3, acquisition);

    const genrePrimeBudget = genrePrimeBudgetForTarget(total);
    progressBox.textContent =
      `Rozszerzam słabo reprezentowane gatunki (do ${genrePrimeBudget} nowych wyszukiwań)...`;
    await primeProfileGenres(token, mixProfiles, genrePrimeBudget, acquisition);

    const remainingSearchBudget = Math.max(0, maxNewSearchesThisGeneration - newSearchesThisGeneration);
    progressBox.textContent = "Szukam wspólnego mianownika i różnych kwalifikowalnych wykonawców...";
    await primeCommonGroupQueries(token, mixProfiles, Math.min(3, remainingSearchBudget), acquisition);

    progressBox.textContent = "Buduję model grupowy: satysfakcja, fairness, xQuAD i MMR...";
    const blocklists = generationBlocklists(selected);
    const ctx = buildGroupRecommendationContext(mixProfiles, loadCandidatePool(), createLastFmEvidenceSnapshot());
    const { eligible, stats } = eligibleGroupCandidates(mixProfiles, blocklists, ctx);

    if (!eligible.length) {
      throw new Error("Po filtrach nie został żaden kandydat. Diagnostyka będzie wymagała poluzowania źródeł lub filtrów.");
    }

    const groupResult = selectGroupPlaylist(eligible, total, ctx, stats);
    groupResult.acquisition = { before: acquisition.before, after: acquisitionCoverage(mixProfiles, blocklists).artists, cachedPages: acquisition.cachedPages, newSearches: newSearchesThisGeneration };
    const finalTracks = sequencePlaylistForListening(groupResult.tracks, 5);
    groupResult.tracks = finalTracks;

    if (!finalTracks.length) {
      throw new Error("Algorytm grupowy nie wybrał żadnego utworu.");
    }

    progressBox.textContent =
      `Tworzę playlistę i zapisuję ${finalTracks.length} utworów...`;

    const playlist = await createPlaylist(token, selected, finalTracks.length);
    await addItemsToPlaylist(
      token,
      playlist.id,
      finalTracks.map(track => track.uri)
    );

    recordSeedArtistSelections(finalTracks, selected);
    // Both Spotify writes have completed. Read fresh evidence again so feedback
    // or history changed while awaiting the API is reflected in diagnostics.
    const diagnosticEvidence = createLastFmEvidenceSnapshot();
    saveRecentPlaylistSnapshot(playlist, finalTracks, selected, total, groupResult, diagnosticEvidence);
    renderPlaylistResult(
      playlist,
      finalTracks,
      selected,
      ignoredProfiles,
      total,
      playlistCleanupResult,
      groupResult,
      diagnosticEvidence
    );

    // Pula Spotify jest kosztowna do odbudowy, więc po udanym generowaniu zapisujemy
    // jej skompaktowaną wersję do D1 razem z trwałymi preferencjami. Błąd chmury
    // nie może unieważnić poprawnie utworzonej playlisty.
    try {
      await uploadCloudStateIfChanged(token, { status: true });
    } catch (cloudErr) {
      console.error("Cloud sync after generation:", cloudErr);
      setCloudStatus(`po generowaniu: ${cloudErr.message}`, "error");
    }
    progressBox.textContent = "";

  } catch (err) {
    console.error(err);
    playlistResult.textContent = err.message;
    playlistBox.style.display = "block";
    progressBox.textContent = "";
  } finally {
    generateButton.disabled = false;
  }
}

functions.saveRecentPlaylistSnapshot:
function saveRecentPlaylistSnapshot(playlist, tracks, selected, requestedTotal, groupResult, evidenceSnapshot = null) {
  const snapshot = {
    id: playlist?.id || `local-${Date.now()}`,
    name: playlist?.name || "Office Music Mixer",
    generatedAt: new Date().toISOString(),
    url: playlist?.external_urls?.spotify || (playlist?.id ? `https://open.spotify.com/playlist/${playlist.id}` : ""),
    uri: playlist?.uri || (playlist?.id ? `spotify:playlist:${playlist.id}` : ""),
    selectedNames: (selected || []).map(p => p.name),
    requestedTotal: Number(requestedTotal || tracks?.length || 0),
    tracks: (tracks || []).map(track => compactTrackForRecent(
      track,
      trackDiagnostic(track, groupResult?.details?.get?.(track.id) || null, selected, evidenceSnapshot)
    ))
  };
  const rows = loadRecentPlaylists().filter(row => row?.id !== snapshot.id);
  rows.unshift(snapshot);
  safeSetSmallStorageItem(RECENT_PLAYLISTS_KEY, JSON.stringify(rows.slice(0, RECENT_PLAYLISTS_MAX)), "ostatnich playlist");
  return snapshot;
}

functions.renderPlaylistResult:
function renderPlaylistResult(
  playlist,
  tracks,
  selected,
  ignoredProfiles = [],
  requestedTotal = tracks.length,
  playlistCleanupResult = null,
  groupResult = null,
  evidenceSnapshot = null
) {
  playlistResult.textContent = "";
  const discoveryTarget = groupResult?.discoveryQuota?.target ?? Number(discoveryLevel.value || 0) / 100;
  const discoveryPercent = Math.round(discoveryTarget * 100);

  const summary = document.createElement("p");
  summary.textContent = tracks.length < requestedTotal
    ? `Utworzono ${tracks.length} z ${requestedTotal} utworów dla: ${selected.map(p => p.name).join(", ")}. Algorytm nie dobija wyniku przypadkowymi utworami tylko po to, żeby zgadzał się licznik.`
    : `Utworzono ${tracks.length} utworów dla: ${selected.map(p => p.name).join(", ")}.`;

  const model = document.createElement("p");
  model.className = "small";
  model.textContent =
    `Model grupowy v43.21.P1: każdy kandydat dostaje osobny wynik dopasowania dla każdej obecnej osoby na podstawie ankiety, artystów wzorcowych i źródeł Last.fm/Spotify. ` +
    `Wynik grupy łączy ważoną średnią z zasadą least misery; Bartek pozostaje profilem głównym (waga 1,3), ale nie ma już sztywnego celu 75%. ` +
    `Fairness mocniej podbija utwory pomagające osobie dotąd słabiej reprezentowanej, xQuAD pilnuje pokrycia różnych lubianych gatunków, a MMR wspiera różnorodność zestawu. Po wyborze zestawu kolejność jest losowana ponownie, z docelowym odstępem co najmniej 5 utworów między tym samym wykonawcą. v36 dodatkowo kanonizuje tytuły przed deduplikacją i mocniej odrzuca wersje live/remix/acoustic/instrumental/edit/version; remaster jest odrzucany, gdy w puli istnieje zwykłe wydanie. v37 dodał awaryjny próg jakości i Polish boost, a v38 pokazał, że końcówkę blokowały głównie dynamiczna quota discovery i zbyt wysoki warunek max profilu. v39 po wyczerpaniu normalnych kandydatów dopuszcza bazowy wynik od 35, jeśli żadna obecna osoba nie ma wyniku poniżej 35; nie wymaga już max profilu ≥65. Wstępny fallback może korzystać z quota docelowej, a v43.21.P1 koryguje końcowy zestaw do górnego limitu faktycznej długości bez obniżania progów jakości. v43 wyklucza utwór we wszystkich ścieżkach, gdy przynajmniej jeden wykonawca ma karę feedbacku <= -40. Ocena utworu ani dodatni feedback współwykonawcy nie omijają tego warunku; wykluczenie nie tworzy trwałej blokady i nie przenosi kary na pozostałych wykonawców. Reguła PR B wymaga wyniku co najmniej 35 dla każdej obecnej osoby przed bonusami grupowymi, zarówno w normalnej selekcji, jak i fallbacku. Polska muzyka zgodna z gustami nadal dostaje malejący bonus na podstawie tagów Last.fm, bez minimalnej kwoty PL. ` +
    `🚫 dla gatunku obniża satysfakcję danej osoby, ale nie blokuje automatycznie całego wykonawcy; jawnie zablokowany wykonawca nadal jest twardym wykluczeniem. ` +
    `Blokada powtórek: faktycznie odtworzony utwór ${trackBlockDays.value} dni, wykonawca ${artistCooldownHours.value} godz. Samo wygenerowanie playlisty nie blokuje utworu. ` +
    `Odkrycia: cel ${discoveryPercent}% z tolerancją ±5 p.p. (poza skrajnymi 0/100); normalna selekcja pilnuje quota względem faktycznej długości wyniku, końcowa korekta również w fallbacku egzekwuje górny limit dla faktycznej długości: najpierw uzupełnia lub zastępuje kandydatów, a skraca wynik dopiero przy braku bezpiecznych zamienników. Dolna granica pozostaje celem, bez skracania bezpiecznych list. Górny limit jest zaokrąglany w dół; tryb 0% oznacza wyłącznie znane utwory, a 100% wyłącznie odkrycia. Genre query Spotify jest tylko słabą wskazówką gatunkową; mocniejsze dowody pochodzą z tagów Last.fm. Ten sam wykonawca może pojawić się maks. 2 razy i nie powinien wystąpić bezpośrednio po sobie. ` +
    (groupResult?.acquisition ? `Pozyskiwanie: kwalifikowalni wykonawcy ${groupResult.acquisition.before} → ${groupResult.acquisition.after}; ponownie użyte strony cache ${groupResult.acquisition.cachedPages}; nowe wyszukiwania ${groupResult.acquisition.newSearches}. ` : "") +
    `Wyszukiwania Spotify są buforowane przez 24 h, lokalna pula żyje 30 dni (maks. ${CANDIDATE_POOL_MAX_ITEMS}), a budżet tego generowania wynosił maks. ${maxNewSearchesThisGeneration} nowych wyszukiwań. ` +
    `Last.fm może w tym przebiegu wykonać do ${lastFmTagBudgetForTarget(requestedTotal)} wywołań tagowych (top artists + top tracks), rotując tagi między kolejnymi generowaniami. ` +
    `v42 przed generowaniem odświeża historię Last.fm najwyżej raz na 10 min i bazę tagową najwyżej raz na 60 min; po generowaniu synchronizuje z D1 również skompaktowaną pulę kandydatów Spotify.`;

  playlistResult.append(summary, model);

  const tasteProfiles = selected.filter(profile => profile.taste?.hasSurvey);
  if (tasteProfiles.length) {
    const tasteDiag = document.createElement("p");
    tasteDiag.className = "small";
    tasteDiag.textContent = `Ankieta gustu: ` + tasteProfiles.map(profile => {
      const liked = profile.taste?.likedGenres?.length || 0;
      const ok = profile.taste?.okGenres?.length || 0;
      const no = profile.taste?.blockedGenres?.length || 0;
      const manualSet = new Set((profile.manualGenres || []).map(normalizeGenreName));
      const added = (profile.taste?.likedGenres || []).filter(g => !manualSet.has(normalizeGenreName(g))).length;
      return `${profile.name} ❤️ ${liked}, 🙂 ${ok}, 🚫 ${no}; +${added} gatunków do aktywnego discovery`;
    }).join(" · ") + ".";
    playlistResult.append(tasteDiag);
  }

  if (groupResult) {
    const satisfaction = document.createElement("p");
    satisfaction.className = "small";
    const satParts = selected
      .filter(profile => groupResult.satisfaction?.[profile.id])
      .map(profile => {
        const row = groupResult.satisfaction[profile.id];
        return `${profile.name}: średnia ${Math.round(row.average)}/100, mocne dopasowanie ${row.strong}/${tracks.length}, słabe ${row.weak}`;
      });
    const discoveryPct = tracks.length
      ? Math.round((Number(groupResult.discoveryCount || 0) / tracks.length) * 100)
      : 0;
    satisfaction.textContent =
      `Dopasowanie grupowe: ${satParts.join(" · ")}. Odkrycia w wyniku: ${groupResult.discoveryCount || 0}/${tracks.length} (${discoveryPct}%). ` +
      `Polska muzyka rozpoznana przez Last.fm: ${groupResult.polishCount || 0}/${tracks.length}. ` +
      `Quota discovery dla celu ${discoveryPercent}%: dolny cel ${groupResult.discoveryQuota?.min ?? 0}, twarde maksimum ${groupResult.discoveryQuota?.max ?? tracks.length} utworów przy faktycznym wyniku ${tracks.length}; pomocniczy limit selekcji wstępnej dla docelowych ${requestedTotal}: ${groupResult.requestedDiscoveryQuota?.max ?? requestedTotal}.`;
    playlistResult.append(satisfaction);
    if (groupResult.discoveryRepair) {
      const repair = groupResult.discoveryRepair;
      const correction = document.createElement("p");
      correction.className = "small";
      correction.textContent = `Korekta discovery: ${repair.beforeDiscovery}/${repair.beforeLength} → ${repair.afterDiscovery}/${repair.afterLength}; ` +
        `nowych utworów ${repair.added}, pominiętych z doboru wstępnego ${repair.removed}; ` +
        (repair.minimumShortfall
          ? `Discovery poniżej celu: brak bezpiecznych odkryć do dodania w zamówionym limicie bez usuwania znanych utworów; niedobór ${repair.minimumShortfall}. `
          : `Dolny cel discovery spełniony. `) +
        `Discovery powyżej dozwolonego maksimum: ${Math.max(0, repair.afterDiscovery - groupResult.discoveryQuota.max)} po korekcie; ` +
        `nadmiar w doborze wstępnym: ${Math.max(0, repair.beforeDiscovery - discoveryQuotaForTotal(repair.beforeLength, discoveryTarget).max)}.`;
      playlistResult.append(correction);
    }


    const r = groupResult.rejectionStats || {};
    const rejection = document.createElement("p");
    rejection.className = "small";
    rejection.textContent =
      `Diagnostyka filtrów: pula ${r.rawPool || 0} → kwalifikowalne ${r.eligible || 0} → wybrane ${tracks.length}. ` +
      `Odrzucono: 👎 utwór ${r.feedbackTrack || 0}, wariant/live/remix ${r.unwantedVariant || 0}, ` +
      `jawnie blokowany wykonawca ${r.explicitBlockedArtist || 0}, 🚫 wykonawca z feedbacku ${r.feedbackBlockedArtist || 0}, ` +
      `blokada konkretnego Spotify wykonawcy ${r.artistIdExcluded || 0}, kara wykonawcy <= -40 ${r.strongNegativeArtistFeedback || 0}, ` +
      `cooldown wykonawcy ${r.artistCooldown || 0}, utwór słuchany w oknie blokady ${r.recentTrack || 0}, ` +
      `wynik obecnej osoby <35 lub brak poprawnej oceny ${r.lowIndividualFit || 0}, ` +
      `znany utwór przy trybie 100% discovery ${r.discoveryModeExcluded || 0}, ` +
      `filtr rozpoznawalności ${r.recognizability || 0}, zbyt słabe dopasowanie grupowe ${r.lowGroupFit || 0}, ` +
      `dobrane przez próg awaryjny ${r.fallbackSelections || 0}` +
      (r.lowFinalScoreStop ? `, kandydaci poza końcowym zestawem przy skróconym wyniku: ${r.lowFinalScoreStop}` : "") + `.`;
    playlistResult.append(rejection);

    if (r.selectionStopDiagnostics) {
      const d = r.selectionStopDiagnostics;
      const stopDiag = document.createElement("p");
      stopDiag.className = "small";
      stopDiag.textContent =
        `Diagnostyka końcowego zatrzymania: pozostało ${d.remaining || 0}; ` +
        `blokady: duplikat ${d.duplicateBlocked || 0}, limit 2 utworów wykonawcy ${d.artistLimitBlocked || 0}, ` +
        `quota discovery przy długości bieżącej ${d.discoveryQuotaBlockedCurrent || 0}, quota discovery przy celu ${requestedTotal} (max ${d.targetQuotaMax ?? 0}) ${d.discoveryQuotaBlockedTarget || 0}; ` +
        `wybieralnych przy quota docelowej ${d.selectableAtTargetQuota || 0}. Rozkład groupBase: >=44: ${d.base44Plus || 0}, 40-43: ${d.base40to43 || 0}, 35-39: ${d.base35to39 || 0}, <35: ${d.baseBelow35 || 0}. ` +
        `Kandydaci >=35: ${d.fallbackRange || 0}; min profilu <35: ${d.fallbackFailMinUser || 0}, ` +
        `mocny negatywny feedback <= -40: ${d.fallbackStrongNegativeFeedback || 0}, ` +
        `bezpiecznych dla fallbacku: ${d.fallbackSafe || 0}.`;
      playlistResult.append(stopDiag);
    }
  }

  const genreDiagText = tasteGenreDiagnosticText(selected);
  if (genreDiagText) {
    const genreDiag = document.createElement("p");
    genreDiag.className = "small";
    genreDiag.textContent = `Diagnostyka gatunków ❤️: ${genreDiagText}`;
    playlistResult.append(genreDiag);
  }

  const seedDiagText = seedArtistDiagnosticText(selected, tracks);
  if (seedDiagText) {
    const seedDiag = document.createElement("p");
    seedDiag.className = "small";
    seedDiag.textContent = `Diagnostyka artystów wzorcowych: ${seedDiagText}`;
    playlistResult.append(seedDiag);
  }

  if (playlistCleanupResult) {
    const cleanupInfo = document.createElement("p");
    cleanupInfo.className = "small";
    if (playlistCleanupResult.skipped) {
      cleanupInfo.textContent = `Porządki Spotify: znaleziono ${playlistCleanupResult.found || 0} playlist starszych niż 72 h; ${playlistCleanupResult.skipped}.`;
    } else {
      cleanupInfo.textContent = `Porządki Spotify: znaleziono ${playlistCleanupResult.found || 0} playlist starszych niż 72 h, usunięto ${playlistCleanupResult.removed || 0}, nadal widoczne ${playlistCleanupResult.remaining || 0}.` +
        (playlistCleanupResult.unparseable ? ` Pominięto ${playlistCleanupResult.unparseable} playlist Office Music Mixer bez daty możliwej do odczytania z nazwy.` : "");
    }
    playlistResult.append(cleanupInfo);
  }

  if (ignoredProfiles.length) {
    const warning = document.createElement("p");
    warning.className = "small";
    warning.textContent =
      `Bez wpływu na dobór muzyki (profil jeszcze pusty): ${ignoredProfiles
        .map(profile => profile.name)
        .join(", ")}.`;
    playlistResult.append(warning);
  }

  const list = buildRatedTrackList(
    tracks,
    track => trackDiagnostic(track, groupResult?.details?.get?.(track.id) || null, selected, evidenceSnapshot)
  );
  playlistResult.append(list);
  appendSpotifyPlaylistLinks(playlistResult, playlist);
  renderRecentPlaylistNav(playlist?.id || "");
  playlistBox.style.display = "block";
}
